ST.xhtml:p:
StartEdge(CLK := Start);
(* Acknowledge clears a latched alarm only after the level is safe. *)
IF Level >= cHighLevel THEN
    Alarm := TRUE;
ELSIF gAckCount <> LastAck THEN
    Alarm := FALSE;
END_IF;
LastAck := gAckCount;

(* STOP and alarms win. Release START before starting again. *)
IF Stop OR Alarm THEN
    Enabled := FALSE;
ELSIF StartEdge.Q THEN
    Enabled := TRUE;
END_IF;
Pump := Enabled AND NOT Alarm AND (Level < gSetpoint);
Running := Pump;
(* Each control activation represents 100 ms; no timer state is retained.
   Saturate at 65535 ticks (6553.5 s) instead of wrapping the display. *)
IF Pump AND (RunTicks < UINT#65535) THEN
    RunTicks := RunTicks + 1;
END_IF;
RunTime := RunTicks;

data.source:source:
PROGRAM TankControl
VAR_INPUT
    Level : INT;
    Start : BOOL;
    Stop : BOOL;
END_VAR
VAR_OUTPUT
    Pump : BOOL;
    Alarm : BOOL;
    Running : BOOL;
    RunTime : UINT;
END_VAR
VAR_EXTERNAL
    gSetpoint : INT;
    gAckCount : UDINT;
END_VAR
VAR_EXTERNAL CONSTANT
    cHighLevel : INT;
END_VAR
VAR RETAIN
    RunTicks : UINT;
END_VAR
VAR
    Enabled : BOOL;
    StartEdge : R_TRIG;
    LastAck : UDINT;
END_VAR

StartEdge(CLK := Start);
(* Acknowledge clears a latched alarm only after the level is safe. *)
IF Level >= cHighLevel THEN
    Alarm := TRUE;
ELSIF gAckCount <> LastAck THEN
    Alarm := FALSE;
END_IF;
LastAck := gAckCount;

(* STOP and alarms win. Release START before starting again. *)
IF Stop OR Alarm THEN
    Enabled := FALSE;
ELSIF StartEdge.Q THEN
    Enabled := TRUE;
END_IF;
Pump := Enabled AND NOT Alarm AND (Level < gSetpoint);
Running := Pump;
(* Each control activation represents 100 ms; no timer state is retained.
   Saturate at 65535 ticks (6553.5 s) instead of wrapping the display. *)
IF Pump AND (RunTicks < UINT#65535) THEN
    RunTicks := RunTicks + 1;
END_IF;
RunTime := RunTicks;
END_PROGRAM

ST.xhtml:p:
(* The control instances publish their running flags in the shared %M word. *)
ActivePumps := BOOL_TO_UINT(gPumpBits.0) + BOOL_TO_UINT(gPumpBits.1);
Samples := Samples + 1;

data.source:source:
PROGRAM StationStatistics
VAR_OUTPUT
    ActivePumps : UINT;
END_VAR
VAR_EXTERNAL
    gPumpBits : WORD;
END_VAR
VAR
    Samples : UDINT;
END_VAR

(* The control instances publish their running flags in the shared %M word. *)
ActivePumps := BOOL_TO_UINT(gPumpBits.0) + BOOL_TO_UINT(gPumpBits.1);
Samples := Samples + 1;
END_PROGRAM

CONFIGURATION TankStation
VAR_GLOBAL
    gSetpoint AT %IW3 : INT;
    gPumpBits AT %MW0 : WORD;
    gAckCount : UDINT;
END_VAR
VAR_GLOBAL CONSTANT
    cHighLevel : INT := 90;
END_VAR
RESOURCE Station ON BENCHTOP
    TASK Control (INTERVAL := T#100ms, PRIORITY := 1);
    TASK Statistics (INTERVAL := T#500ms, PRIORITY := 5);
    TASK OnAck (SINGLE := %IX0.4, PRIORITY := 0);
    PROGRAM Tank1 WITH Control : TankControl (
        Level := %IW1, Start := %IX0.0, Stop := %IX0.1,
        Pump => %QX0.0, Alarm => %QX0.1, Running => %MX0.0, RunTime => %QW1);
    PROGRAM Tank2 WITH Control : TankControl (
        Level := %IW2, Start := %IX0.2, Stop := %IX0.1,
        Pump => %QX0.2, Alarm => %QX0.3, Running => %MX0.1, RunTime => %QW2);
    PROGRAM Stats WITH Statistics : StationStatistics (ActivePumps => %QW3);
    PROGRAM Ack WITH OnAck : Acknowledge;
END_RESOURCE
END_CONFIGURATION
